const payload = $('Execute Workflow Trigger').item.json || {};
const chatId = String(payload.chatId || payload.message?.chat?.id || '').trim();
const query = String(payload.query || payload.text || payload.rawText || '').trim();
const limit = Math.max(1, Math.min(5, Number(payload.limit || 5) || 5));
const escapeSql = (value = '') => String(value || '').replace(/'/g, "''");
if (!chatId) {
  throw new Error('Missing chatId for memory_recall_facts');
}
if (!query) {
  return [{ json: { chatId, query: '', skip: true, responseText: 'MEMORY_FACT_RESULTS\nnone' } }];
}
const q = escapeSql(query);
const searchSql = `SELECT fact_text, category, tags, confidence, updated_at FROM mia_facts WHERE chat_id = '${escapeSql(chatId)}' AND is_active = true AND (fact_text ILIKE '%${q}%' OR category ILIKE '%${q}%' OR array_to_string(tags, ' ') ILIKE '%${q}%') ORDER BY CASE WHEN fact_text ILIKE '${q}%' THEN 0 ELSE 1 END, updated_at DESC LIMIT ${limit};`;
return [{ json: { chatId, query, skip: false, searchSql } }];

const source = $('Prepare Recall Facts').item.json || {};
if (source.skip) {
  return [{ json: { text: source.responseText, chatId: source.chatId || '' } }];
}
const rows = $input.all().map((item) => item.json || {}).filter((row) => row.fact_text);
if (rows.length === 0) {
  return [{ json: { text: `MEMORY_FACT_RESULTS\nquery: ${source.query}\nnone`, chatId: source.chatId || '' } }];
}
const lines = ['MEMORY_FACT_RESULTS', `query: ${source.query}`];
rows.forEach((row, index) => {
  const tags = Array.isArray(row.tags) && row.tags.length ? ` | tags=${row.tags.join(', ')}` : '';
  lines.push(`${index + 1}. [${row.category || 'general'}] ${row.fact_text}${tags}`);
});
return [{ json: { text: lines.join('\n'), chatId: source.chatId || '' } }];
